<?php require_once __DIR__.'/../includes/auth.php';header('Content-Type: application/json');$u=current_user();if(!$u||$u['role']!=='customer'){http_response_code(403);echo json_encode(['ok'=>false,'message'=>'Customer login required.']);exit;}$token=$_POST['csrf_token']??'';if(!$token||!hash_equals($_SESSION['csrf_token']??'',$token)){http_response_code(419);echo json_encode(['ok'=>false,'message'=>'Session expired.']);exit;}$target=(int)($_POST['target_user_id']??0);$q=db()->prepare("SELECT id FROM users WHERE id=? AND role IN('provider','business') AND status='active'");$q->execute([$target]);if(!$q->fetch()){http_response_code(404);echo json_encode(['ok'=>false,'message'=>'Provider not found.']);exit;}if(is_favorite((int)$u['id'],$target)){db()->prepare('DELETE FROM favorites WHERE customer_id=? AND target_user_id=?')->execute([$u['id'],$target]);echo json_encode(['ok'=>true,'favorite'=>false]);}else{db()->prepare('INSERT IGNORE INTO favorites(customer_id,target_user_id) VALUES(?,?)')->execute([$u['id'],$target]);echo json_encode(['ok'=>true,'favorite'=>true]);}
